#!/bin/bash
# build libplist (static) and UxPlay's lib/ (airplay, playfair, llhttp, dns_sd glue) for the head unit
set -e
A=$HOME/airplay; CC=$A/zcc; AR=$A/zar
B=$A/build; mkdir -p $B/plist $B/uxlib
INC="-I$A/sysroot/include -I$A/src/openssl-1.1.1g/include"

# openssl 1.1.1g public headers need opensslconf.h, normally generated by Configure
if [ ! -f $A/src/openssl-1.1.1g/include/openssl/opensslconf.h ]; then
  (cd $A/src/openssl-1.1.1g && CC=$CC ./Configure linux-x86_64 no-asm no-shared >/dev/null && make include/openssl/opensslconf.h >/dev/null)
fi

# libplist 2.6.0 (no autotools: compile the sources directly)
P=$A/src/libplist
cd $B/plist; rm -f *.o
# stands in for the config.h autotools would generate (glibc 2.27 has all of these)
cat > config.h <<'EOF'
#define HAVE_TM_TM_GMTOFF 1
#define HAVE_TM_TM_ZONE 1
#define HAVE_LOCALTIME_R 1
#define HAVE_GMTIME_R 1
#define HAVE_TIMEGM 1
#define HAVE_STRPTIME 1
#define HAVE_MEMMEM 1
#define HAVE_STRNDUP 1
#define HAVE_ATTRIBUTE_CONSTRUCTOR 1
#define PACKAGE_VERSION "2.6.0"
#define PACKAGE_STRING "libplist 2.6.0"
EOF
for f in $P/src/*.c $P/libcnary/*.c; do
  [ "$(basename $f)" = cnary.c ] && continue   # a test program with its own main()
  $CC -O2 -fPIC -DHAVE_CONFIG_H -I$B/plist -D_GNU_SOURCE \
      -I$P/include -I$P/src -I$P/libcnary/include -c "$f" -o "$(basename "${f%.c}").o" 2> err.txt || { echo "plist: $f"; cat err.txt | head -20; exit 1; }
done
rm -f $A/sysroot/lib/libplist-2.0.a $A/sysroot/lib/libairplay.a
$AR rcs $A/sysroot/lib/libplist-2.0.a *.o
mkdir -p $A/sysroot/include/plist; cp $P/include/plist/*.h $A/sysroot/include/plist/

# UxPlay lib
U=$A/src/UxPlay/lib
cd $B/uxlib; rm -f *.o
FL="-O2 -fPIC -DSTANDALONE -D__STDC_CONSTANT_MACROS -D__STDC_LIMIT_MACROS -DTARGET_POSIX -D_LINUX -D_REENTRANT -D_LARGEFILE64_SOURCE -D_FILE_OFFSET_BITS=64 -DNOHOLD -DPLIST_230 -DPLIST_210 -D_GNU_SOURCE"
for f in $U/*.c $U/playfair/*.c $U/llhttp/*.c $U/dns_sd/*.c; do
  o=$(echo "${f#$U/}" | tr / _); o=${o%.c}.o
  $CC $FL $INC -I$U -I$U/playfair -I$U/llhttp -c "$f" -o "$o" 2> err.txt || { echo "uxlib: $f"; head -30 err.txt; exit 1; }
done
$AR rcs $A/sysroot/lib/libairplay.a *.o
ls -la $A/sysroot/lib/*.a
